for attempt in range(2):
    inv = extract(doc, feedback)
    errors = []
    if abs(sum(l.amount for l in inv.lines) - inv.stated_total) > 0.01:
        errors.append(f"lines sum to {sum(l.amount for l in inv.lines):.2f}, stated_total is {inv.stated_total:.2f}")
    if inv.due_date and inv.due_date < inv.issue_date:
        errors.append("due_date is before issue_date")
    if not errors:
        return inv
    feedback = "Fix these issues, re-reading the document:\n" + "\n".join(errors)
return send_to_review(doc, inv, errors)

